-- ---------------------------------------------
-- column_size: mirrors COL_LENGTH (bytes).
-- Returns NULL if the column does not exist.
-- ---------------------------------------------

CREATE OR ALTER FUNCTION mold.column_size (@name nvarchar(1000))
RETURNS int
AS
BEGIN
    RETURN (SELECT max_length FROM mold.column_info(@name));
END;
GO


-- ---------------------------------------------
-- column_length: logical length for string columns.
--   varchar  -> max_length
--   nvarchar -> max_length / 2
--   text, ntext -> -1
--   other    -> 0
-- Returns NULL if the column does not exist.
-- ---------------------------------------------

CREATE OR ALTER FUNCTION mold.column_length (@name nvarchar(1000))
RETURNS int
AS
BEGIN
    DECLARE @type sysname, @max_len smallint;

    SELECT @type = type_name, @max_len = max_length
    FROM mold.column_info(@name);

    IF @type IS NULL
        RETURN NULL;

    RETURN CASE
        WHEN @type IN (N'varchar', N'char', N'varbinary', N'binary')
            THEN @max_len
        WHEN @type IN (N'nvarchar', N'nchar')
            THEN @max_len / 2
        WHEN @type IN (N'text', N'ntext', N'image')
            THEN -1
        ELSE 0
    END;
END;
GO

